CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS app_users (id BIGSERIAL PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, name VARCHAR(160) NOT NULL, phone VARCHAR(40), role VARCHAR(32) NOT NULL DEFAULT 'customer', is_active SMALLINT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS app_users_role_idx ON app_users(role);
CREATE INDEX IF NOT EXISTS app_users_active_idx ON app_users(is_active);
CREATE TABLE IF NOT EXISTS app_sessions (token_hash CHAR(64) PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES app_users(id) ON DELETE CASCADE, expires_at TIMESTAMPTZ NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS app_sessions_user_idx ON app_sessions(user_id);
CREATE INDEX IF NOT EXISTS app_sessions_expiry_idx ON app_sessions(expires_at);
CREATE TABLE IF NOT EXISTS catalog_categories (id BIGSERIAL PRIMARY KEY, slug VARCHAR(120) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, description TEXT, image_url TEXT, is_active SMALLINT NOT NULL DEFAULT 1, sort_order INT NOT NULL DEFAULT 0, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS catalog_products (id VARCHAR(64) PRIMARY KEY, slug VARCHAR(200) NOT NULL UNIQUE, name VARCHAR(200) NOT NULL, base_price_usd NUMERIC(12,2) NOT NULL, sale_price_usd NUMERIC(12,2), rating NUMERIC(3,2) NOT NULL DEFAULT 0, review_count INT NOT NULL DEFAULT 0, tags_json JSONB NOT NULL, image_url TEXT NOT NULL, image_card_url TEXT NOT NULL, is_hot SMALLINT NOT NULL DEFAULT 0, shop_order INT NOT NULL DEFAULT 0, featured_order INT, recent_order INT, deal_order INT, short_description TEXT NOT NULL, description_json JSONB NOT NULL, release_year INT NOT NULL, developer VARCHAR(200) NOT NULL, platform VARCHAR(255) NOT NULL, is_active SMALLINT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS catalog_products_active_idx ON catalog_products(is_active);
CREATE INDEX IF NOT EXISTS catalog_products_shop_order_idx ON catalog_products(shop_order);
CREATE TABLE IF NOT EXISTS catalog_product_categories (product_id VARCHAR(64) NOT NULL REFERENCES catalog_products(id) ON DELETE CASCADE, category_id BIGINT NOT NULL REFERENCES catalog_categories(id) ON DELETE CASCADE, PRIMARY KEY(product_id, category_id));
CREATE TABLE IF NOT EXISTS content_posts (slug VARCHAR(200) PRIMARY KEY, title VARCHAR(255) NOT NULL, published_date DATE NOT NULL, category VARCHAR(120) NOT NULL, author VARCHAR(160) NOT NULL, image_url TEXT NOT NULL, image_card_url TEXT NOT NULL, image_thumb_url TEXT NOT NULL, excerpt TEXT NOT NULL, tags_json JSONB NOT NULL, views INT NOT NULL DEFAULT 0, comments_count INT NOT NULL DEFAULT 0, blocks_json JSONB NOT NULL, status VARCHAR(24) NOT NULL DEFAULT 'published', published_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS content_posts_status_idx ON content_posts(status);
CREATE INDEX IF NOT EXISTS content_posts_date_idx ON content_posts(published_date);
CREATE TABLE IF NOT EXISTS site_settings (setting_key VARCHAR(160) PRIMARY KEY, value_json JSONB NOT NULL, updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS site_banners (id BIGSERIAL PRIMARY KEY, slug VARCHAR(160) NOT NULL UNIQUE, title VARCHAR(255) NOT NULL, description TEXT, image_url TEXT NOT NULL, button_label VARCHAR(120), href VARCHAR(500), variant VARCHAR(40) NOT NULL DEFAULT 'homepage', sort_order INT NOT NULL DEFAULT 0, is_active SMALLINT NOT NULL DEFAULT 1, starts_at TIMESTAMPTZ, ends_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS site_banners_active_idx ON site_banners(is_active, sort_order);
CREATE TABLE IF NOT EXISTS shop_orders (id BIGSERIAL PRIMARY KEY, order_number VARCHAR(64) NOT NULL UNIQUE, access_token_hash CHAR(64) NOT NULL UNIQUE, user_id BIGINT REFERENCES app_users(id) ON DELETE SET NULL, customer_name VARCHAR(180) NOT NULL, customer_email VARCHAR(255) NOT NULL, customer_phone VARCHAR(40) NOT NULL, billing_address TEXT, billing_city VARCHAR(120), billing_province VARCHAR(120), subtotal_aoa NUMERIC(14,2) NOT NULL, discount_aoa NUMERIC(14,2) NOT NULL DEFAULT 0, total_aoa NUMERIC(14,2) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'AOA', exchange_rate_usd_aoa NUMERIC(14,4) NOT NULL, status VARCHAR(40) NOT NULL DEFAULT 'awaiting_payment', payment_status VARCHAR(40) NOT NULL DEFAULT 'pending', payment_method VARCHAR(80), internal_notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS shop_orders_user_idx ON shop_orders(user_id);
CREATE INDEX IF NOT EXISTS shop_orders_email_idx ON shop_orders(customer_email);
CREATE INDEX IF NOT EXISTS shop_orders_status_idx ON shop_orders(status, payment_status);
CREATE TABLE IF NOT EXISTS shop_order_items (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES shop_orders(id) ON DELETE CASCADE, product_id VARCHAR(64) NOT NULL, product_name VARCHAR(200) NOT NULL, unit_price_aoa NUMERIC(14,2) NOT NULL, quantity INT NOT NULL, subtotal_aoa NUMERIC(14,2) NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS shop_order_items_order_idx ON shop_order_items(order_id);
CREATE TABLE IF NOT EXISTS shop_order_status_history (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES shop_orders(id) ON DELETE CASCADE, from_status VARCHAR(40), to_status VARCHAR(40) NOT NULL, note TEXT, changed_by_user_id BIGINT REFERENCES app_users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS shop_order_history_order_idx ON shop_order_status_history(order_id, created_at);
CREATE TABLE IF NOT EXISTS shop_payments (id BIGSERIAL PRIMARY KEY, order_id BIGINT NOT NULL REFERENCES shop_orders(id) ON DELETE CASCADE, provider VARCHAR(80) NOT NULL, provider_payment_id VARCHAR(255), status VARCHAR(40) NOT NULL DEFAULT 'pending', amount_aoa NUMERIC(14,2) NOT NULL, currency CHAR(3) NOT NULL DEFAULT 'AOA', failure_reason TEXT, paid_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(provider, provider_payment_id));
CREATE INDEX IF NOT EXISTS shop_payments_order_idx ON shop_payments(order_id);
CREATE TABLE IF NOT EXISTS admin_audit_logs (id BIGSERIAL PRIMARY KEY, user_id BIGINT REFERENCES app_users(id) ON DELETE SET NULL, action VARCHAR(120) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id VARCHAR(120), metadata_json JSONB, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS admin_audit_logs_entity_idx ON admin_audit_logs(entity_type, entity_id);
CREATE INDEX IF NOT EXISTS admin_audit_logs_user_idx ON admin_audit_logs(user_id, created_at);
